import { after } from 'next/server'
import { cacheLife, cacheTag, revalidateTag } from 'next/cache'
import { getAllProducts, getCatalogStatus, syncProductCatalog } from '@/lib/db'

async function getProductsSnapshot() {
  'use cache'
  cacheLife('max')
  cacheTag('products')

  const [products, status] = await Promise.all([getAllProducts(), getCatalogStatus()])

  return { products, status }
}

export default async function ProductCatalogPage() {
  const { products, status } = await getProductsSnapshot()

  async function syncLatestCatalog() {
    'use server'

    after(async () => {
      await syncProductCatalog()
      revalidateTag('products')
    })
  }

  return (
    <main>
      <h1>Product catalog</h1>
      <p>
        Catalog version: {status.catalogVersion}
        {' · '}
        Last synced: {status.lastSyncedAt ?? 'never'}
      </p>

      <form action={syncLatestCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <ul>
